function showEvent(s){let t=el('eventToast');t.textContent=s;t.classList.add('show');clearTimeout(showEvent.timer);showEvent.timer=setTimeout(()=>t.classList.remove('show'),4200)}
function advanceMonth(){let q=economy(),before=state.population,houses=0,unserved=0,amenity=false;
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){let c=state.grid[y][x];if(!c.zone||c.building||!roadNear(x,y))continue;let utilities=utility(x,y,'power',8)&&utility(x,y,'water',8);if(!utilities||q.d[c.zone]<21||state.happy<28||Math.random()>.32)continue;c.building=c.zone;c.level=1;if(c.zone==='res'){let add=7+Math.floor(Math.random()*10);state.population+=add;addLog('새 주택에 주민이 이사 왔어요. 인구 +'+add)}else{let add=6+Math.floor(Math.random()*14);state.jobs+=add;addLog((c.zone==='com'?'상가':'수산·조선 시설')+'이 문을 열어 일자리가 늘었어요.')}}
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){let c=state.grid[y][x];if(c.zone&&c.building&&utility(x,y,'power',8)&&utility(x,y,'water',8)&&Math.random()<.16&&c.level<4)c.level++;if(c.zone==='res'&&c.building){houses++;if(!utility(x,y,'power',8)||!utility(x,y,'water',8))unserved++;if(covered(x,y,'clinic',6)||covered(x,y,'school',6)||covered(x,y,'park',5))amenity=true}}
 state.lastPopDelta=state.population-before;state.money+=q.tax-q.upkeep;state.happy=Math.max(20,Math.min(100,state.happy+(amenity?1:0)+(q.env>82?1:0)-(houses&&unserved>houses/2?2:0)-(q.traffic==='정체'?1:0)));state.month++;if(state.month>12){state.month=1;state.year++}
 addLog('월말 정산 · 세금 +'+q.tax.toLocaleString()+'원 · 유지비 −'+q.upkeep.toLocaleString()+'원');if(state.money<0){state.happy=Math.max(20,state.happy-3);addLog('예산이 적자예요. 세금과 시설 지출을 조정해 보세요.')}if(state.eventCooldown>0)state.eventCooldown--;else if(Math.random()<.33)eventPop();renderUI();rebuildCity()}
function setSpeed(n){speed=n;document.querySelectorAll('.speed').forEach(b=>b.classList.toggle('selected',Number(b.dataset.speed)===n));el('pause').textContent=n?'Ⅱ':'▶';el('clock').textContent=n?'자동 진행 · '+n+'×':'일시 정지';el('clock').parentElement.classList.toggle('paused',!n)}
function renderTools(){[el('toolbar'),el('mobileToolbar')].forEach(nav=>{nav.innerHTML='';tools.forEach((t,i)=>{if(nav.id==='toolbar'&&[1,6,12].includes(i)){let hr=document.createElement('i');hr.className='tool-divider';nav.appendChild(hr)}let b=document.createElement('button');b.className='tool'+(active===t[0]?' active':'');b.innerHTML='<span class="ico">'+t[1]+'</span><span>'+t[2]+'</span>';b.title=defs[t[0]]?.desc||'지도 살펴보기';b.onclick=()=>{active=t[0];document.querySelectorAll('.tool').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.tool').forEach(x=>{if(x.textContent.includes(t[2]))x.classList.add('active')});el('selectedInfo').innerHTML='<h3>'+t[1]+' '+(defs[t[0]]?.name||'지도 선택')+'</h3><p>'+(defs[t[0]]?defs[t[0]].desc+(defs[t[0]].cost?' · '+defs[t[0]].cost+'원':''):'지도를 눌러 정보를 확인하세요.')+'</p>';toast(t[2]+' 도구 선택')};nav.appendChild(b)})})}
function renderUI(){let q=economy();el('calendar').textContent=['🌱 봄','☀️ 여름','🍂 가을','❄️ 겨울'][Math.floor((state.month-1)/3)]+' · '+state.year+'년차 '+state.month+'월';el('money').textContent='₩'+state.money.toLocaleString();el('population').textContent=state.population.toLocaleString()+'명';el('jobs').textContent=state.jobs.toLocaleString()+'개';el('happiness').textContent=state.happy+'%';el('happyBar').style.width=state.happy+'%';el('popDelta').textContent=(state.lastPopDelta>=0?'+':'')+state.lastPopDelta;el('taxIncome').textContent='+'+q.tax.toLocaleString()+'원';el('upkeep').textContent='−'+q.upkeep.toLocaleString()+'원';el('traffic').textContent=q.traffic;el('environment').textContent=q.env+'%';el('powerStatus').textContent=q.c.f.power?'전력 공급':'발전소 필요';[['res','Res'],['com','Com'],['ind','Ind']].forEach(a=>el('demand'+a[1]).style.width=q.d[a[0]]+'%');let f=q.c.f,services=[['⚡ 전기',f.power?'공급':'부족',f.power],['💧 물',f.water?'공급':'부족',f.water],['🏥 보건',f.clinic?'운영':'없음',f.clinic],['🏫 교육',f.school?'운영':'없음',f.school],['🚒 소방',f.fire?'운영':'없음',f.fire],['🚓 치안',f.police?'운영':'없음',f.police]];el('services').innerHTML=services.map(a=>'<div class="service '+(a[2]?'':'off')+'"><span>'+a[0]+'</span><b>'+a[1]+'</b></div>').join('');['res','com','ind'].forEach(k=>{let n=k[0].toUpperCase()+k.slice(1);el('tax'+n).value=state.tax[k];el('tax'+n+'Value').textContent=state.tax[k]+'%'});
 if(selected){let c=state.grid[selected.y][selected.x];el('coord').textContent='CELL '+(selected.x+1)+','+(selected.y+1);let title=c.building?defs[c.building].icon+' '+defs[c.building].name:c.road?'🛣️ 도로':c.zone?'📍 '+defs[c.zone].name:c.terrain==='water'?'🌊 바다 타일':c.terrain==='shore'?'🏖️ 해안':'🌿 자연 지형';let note=c.building?defs[c.building].desc:c.zone?'도로 인접 '+(roadNear(selected.x,selected.y)?'· 연결됨':'· 도로 필요')+' / '+(c.building?'레벨 '+c.level:'건물 대기 중'):c.road?'거제 도시 도로망에 연결되어 있습니다.':'도로 옆 타일에 구역을 지정할 수 있어요.';el('selectedInfo').innerHTML='<h3>'+title+'</h3><p>'+note+'</p>'}else el('coord').textContent=W+' × '+H+' 섬 지도';
 el('log').innerHTML=state.logs.map(x=>'<div>'+x+'</div>').join('');localStorage.setItem(KEY,JSON.stringify(state))}
function placeAt(x,y){if(!landCell(x,y))return toast('바다에는 건설할 수 없어요.');let c=state.grid[y][x];if(active==='inspect'){selected={x,y};renderUI();rebuildCity();return}if(active==='bulldoze'){if(!c.road&&!c.zone&&!c.building)return;let t=c.building||c.zone||'road';if(defs[t])state.money+=Math.floor(defs[t].cost*.25);c.road=false;c.zone=null;c.building=null;c.level=0;selected={x,y};addLog('선택한 도로와 시설을 철거했어요.');renderUI();rebuildCity();return}if(c.road||c.zone||c.building)return toast('이미 도로나 시설이 있는 자리예요.');if(!roadNear(x,y))return toast('도로와 맞닿은 땅을 선택하세요.');let d=defs[active];if(!d)return;if(state.money<d.cost)return toast('도시 자금이 부족해요.');state.money-=d.cost;if(active==='road')c.road=true;else if(['res','com','ind'].includes(active))c.zone=active;else c.building=active;selected={x,y};addLog(d.name+'을 설치했어요.');renderUI();rebuildCity();toast(d.name+' 설치 완료');beep(620)}
let down=null;function onDown(e){down={x:e.clientX,y:e.clientY}}function onUp(e){if(!down)return;let moved=Math.hypot(e.clientX-down.x,e.clientY-down.y);down=null;if(moved>5)return;let p=cellUnderPointer(e);if(p)placeAt(p.x,p.y)}
function beep(f){if(!sound)return;try{audio=audio||new AudioContext();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=f;g.gain.setValueAtTime(.03,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.start();o.stop(audio.currentTime+.12)}catch(e){}}
function setupUI(){renderTools();el('pause').onclick=()=>setSpeed(speed?0:1);document.querySelectorAll('.speed').forEach(b=>b.onclick=()=>setSpeed(Number(b.dataset.speed)));el('zoomIn').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(.86);controls.update()};el('zoomOut').onclick=()=>{camera.position.sub(controls.target).multiplyScalar(1.16);controls.update()};el('resetCamera').onclick=()=>{camera.position.set(0,52,62);controls.target.set(-.2,.6,.4);controls.update()};el('sound').onclick=()=>{sound=!sound;el('sound').textContent=sound?'♪':'♫';beep(540)};[['res','Res'],['com','Com'],['ind','Ind']].forEach(a=>el('tax'+a[1]).oninput=e=>{state.tax[a[0]]=Number(e.target.value);renderUI()});renderer.domElement.addEventListener('pointerdown',onDown);renderer.domElement.addEventListener('pointerup',onUp);renderer.domElement.addEventListener('pointermove',e=>{let p=cellUnderPointer(e);if(p&&(p.x!==selected?.x||p.y!==selected?.y)){/* hover is kept lightweight */}});window.addEventListener('resize',resize);setSpeed(1)}
function start(){try{initThree();setupUI();rebuildCity();renderUI()}catch(e){console.error(e);el('loading').innerHTML='<b>3D 지도를 불러오지 못했어요</b><small>WebGL을 지원하는 최신 브라우저에서 다시 열어 주세요.</small>'}}
start();
